static const char *cg_builtin_canonical_name_for_kind(CGTypeKind kind) {
    switch (kind) {
        case CG_TYPE_BOOL: return "bool";
        case CG_TYPE_I8: return "i8";
        case CG_TYPE_I16: return "i16";
        case CG_TYPE_I32: return "i32";
        case CG_TYPE_I64: return "i64";
        case CG_TYPE_U8: return "u8";
        case CG_TYPE_U16: return "u16";
        case CG_TYPE_U32: return "u32";
        case CG_TYPE_U64: return "u64";
        case CG_TYPE_F32: return "f32";
        case CG_TYPE_F64: return "f64";
        case CG_TYPE_STRING: return "string";
        default: return NULL;
    }
}

/* ===================== error helpers ===================== */

static char *cg_vformat(const char *fmt, va_list ap) {
    va_list ap2;
    va_copy(ap2, ap);
    int n = vsnprintf(NULL, 0, fmt, ap);
    if (n < 0) { va_end(ap2); return NULL; }
    char *p = malloc((size_t)n + 1);
    if (p) vsnprintf(p, (size_t)n + 1, fmt, ap2);
    va_end(ap2);
    return p;
}

static bool cg_fail(CG *cg, FengToken token, const char *code, const char *fmt, ...) {
    if (cg->failed) return false;
    cg->failed = true;
    if (cg->error) {
        va_list ap;
        va_start(ap, fmt);
        cg->error->message = cg_vformat(fmt, ap);
        va_end(ap);
        cg->error->code = code;
        cg->error->token = token;
        /* Pin the diagnostic to the source program currently being emitted.
         * Without this the CLI falls back to sources[0].path which, in
         * multi-file projects, is the first input alphabetically — almost
         * never the file the failing token actually came from. */
        if (!cg->error->path && cg->cur_program) {
            cg->error->path = cg->cur_program->path;
        }
    }
    return false;
}

/* Returns true when this codegen run should collect abstract debug metadata. */
static bool cg_debug_enabled(const CG *cg) {
    return cg != NULL &&
           cg->options != NULL &&
           cg->options->debug_source_mappings != NULL &&
           cg->options->debug_source_mapping_count > 0U;
}

/* Duplicates one Feng identifier slice into a temporary C string. */
static char *cg_dup_slice(FengSlice slice) {
    return strndup(slice.data, slice.length);
}

/* Adds one frame mapping to the abstract debug-info output. */
static bool cg_debug_add_frame_record(CG *cg,
                                      const char *backend_symbol,
                                      const char *display_name,
                                      FengCodegenMapingFramePolicy policy,
                                      FengToken blame) {
    if (!cg_debug_enabled(cg)) {
        return true;
    }
    if (!feng_codegen_maping_info_add_frame(&cg->debug_info,
                                   backend_symbol,
                                   display_name,
                                   policy)) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory recording debug frame");
    }
    return true;
}

/* Activates one backend frame so later variable records can attach to it. */
static bool cg_debug_set_current_frame(CG *cg,
                                       const char *backend_symbol,
                                       const char *display_name,
                                       FengCodegenMapingFramePolicy policy,
                                       FengToken blame) {
    if (!cg_debug_add_frame_record(cg,
                                   backend_symbol,
                                   display_name,
                                   policy,
                                   blame)) {
        return false;
    }
    cg->current_frame_backend_symbol = backend_symbol;
    return true;
}

static char *cg_debug_dup_display_type_from_type_ref(const FengTypeRef *type_ref) {
    Buf out;

    if (type_ref == NULL) {
        return NULL;
    }
    buf_init(&out);
    cg_append_type_ref_display(&out, type_ref);
    return out.data;
}

static char *cg_debug_dup_display_type_from_cgtype(CG *cg,
                                                   const CGType *type,
                                                   FengToken blame) {
    FengTypeRef *type_ref;
    FengTypeRef *qualified_ref;
    char *display_type;

    if (cg == NULL || type == NULL) {
        return NULL;
    }
    type_ref = cg_type_ref_from_cgtype(cg, type, blame);
    if (type_ref == NULL) {
        return NULL;
    }
    qualified_ref = cg_debug_qualify_type_ref(cg, type_ref);
    cg_type_ref_free(type_ref);
    if (qualified_ref == NULL) {
        return NULL;
    }
    display_type = cg_debug_dup_display_type_from_type_ref(qualified_ref);
    cg_type_ref_free(qualified_ref);
    return display_type;
}

/* Adds one variable mapping that already has a C-string display name. */
static bool cg_debug_add_variable_record_cstr_typed(CG *cg,
                                                    const char *backend_name,
                                                    const char *display_name,
                                                    const char *read_expr,
                                                    const char *display_type,
                                                    FengCodegenMapingVariableKind kind,
                                                    FengToken blame) {
    if (!cg_debug_enabled(cg) ||
        cg->current_frame_backend_symbol == NULL ||
        display_name == NULL) {
        return true;
    }
    if (!feng_codegen_maping_info_add_variable_with_display_type(
            &cg->debug_info,
            cg->current_frame_backend_symbol,
            backend_name,
            display_name,
            read_expr,
            display_type,
            kind)) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory recording debug variable");
    }
    return true;
}

/* Adds one variable mapping keyed by a Feng identifier slice. */
static bool cg_debug_add_variable_record_slice_typed(CG *cg,
                                                     const char *backend_name,
                                                     FengSlice display_name,
                                                     const char *read_expr,
                                                     const char *display_type,
                                                     FengCodegenMapingVariableKind kind,
                                                     FengToken blame) {
    char *name = cg_dup_slice(display_name);
    bool ok;

    if (name == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory recording debug variable");
    }
    ok = cg_debug_add_variable_record_cstr_typed(cg,
                                                 backend_name,
                                                 name,
                                                 read_expr,
                                                 display_type,
                                                 kind,
                                                 blame);
    free(name);
    return ok;
}

static bool cg_debug_add_variable_record_cstr_type_ref(CG *cg,
                                                       const char *backend_name,
                                                       const char *display_name,
                                                       const char *read_expr,
                                                       const FengTypeRef *type_ref,
                                                       FengCodegenMapingVariableKind kind,
                                                       FengToken blame) {
    FengTypeRef *qualified_ref = cg_debug_qualify_type_ref(cg, type_ref);
    char *display_type = cg_debug_dup_display_type_from_type_ref(
        qualified_ref != NULL ? qualified_ref : type_ref);
    bool ok;

    cg_type_ref_free(qualified_ref);
    if (display_type == NULL) {
        return cg_fail(cg, blame, "CE0001", "codegen: missing debug display type");
    }
    ok = cg_debug_add_variable_record_cstr_typed(cg,
                                                 backend_name,
                                                 display_name,
                                                 read_expr,
                                                 display_type,
                                                 kind,
                                                 blame);

    free(display_type);
    return ok;
}

